"use client";

// FiveStarRatingPicker component
//
// A five-star rating input that lets users select a rating from 1 to 5 stars using
// radio buttons. This is one of the most common rating patterns on the web, used for
// product reviews, content ratings, and feedback forms. Each radio button is labeled
// with "N star" or "N stars" for clear screen reader communication.
//
// Props:
//   className — string, optional. CSS class name.
//   label — string, required. Accessible name for the rating group via aria-label.
//   value — number, default 0. Current rating (1-5, 0 = none); bindable via value + onChange.
//   name — string, default "rating". Radio group name for form submission.
//   disabled — boolean, default false. Whether the entire group is disabled.
//   ...restProps — additional HTML attributes spread onto the fieldset.
//
// Syntax:
//   <FiveStarRatingPicker label="Rate this" value={value} onChange={setValue} />
//
// Examples:
//
//   <FiveStarRatingPicker label="Rate this product" value={rating} onChange={setRating} />
//
//
//   <FiveStarRatingPicker label="Your rating" value={value} onChange={setValue} disabled />
//
// Keyboard:
//   - Tab: Focus the selected radio (or first if none selected)
//   - ArrowDown / ArrowRight: Move to next radio button
//   - ArrowUp / ArrowLeft: Move to previous radio button
//   - Space: Select the focused radio button
//
// Accessibility:
//   - role="radiogroup" on the fieldset identifies the group as a set of radio buttons
//   - aria-label provides an accessible name for the entire rating group
//   - Each radio label reads "1 star", "2 stars", etc. for screen reader clarity
//
// Internationalization:
//   - The label prop allows localized accessible names
//   - Star labels ("N star"/"N stars") are in the template; consumer can override via restProps
//
// Claude rules:
//   - Headless: no CSS, no styles — consumer provides all styling
//   - Uses native radio buttons for built-in keyboard and accessibility behavior
//   - Value 0 means no selection; valid ratings are 1-5
//
// References:
//   - WAI-ARIA Radio Group Pattern: https://www.w3.org/WAI/ARIA/apg/patterns/radiobutton/

import React, { useEffect, useRef, useState } from "react";

export interface FiveStarRatingPickerProps {
    className?: string;
    /** Accessible name for the rating group via aria-label. */
    label: string;
    /** Current rating (1-5, 0 = none). Bindable via value + onChange. */
    value?: number;
    /** Radio group name for form submission. */
    name?: string;
    /** Each option's text, e.g. (n) => `${n} stars`. Defaults to the number alone: no English default. */
    starLabel?: (star: number) => string;
    /** Whether the entire group is disabled. */
    disabled?: boolean;
    /** Callback when value changes. */
    onChange?: (value: number) => void;
    [key: string]: unknown;
}

export default function FiveStarRatingPicker({
    className = "",
    label,
    value: valueProp = 0,
    name = "rating",
    starLabel,
    disabled = false,
    onChange,
    ...restProps
}: FiveStarRatingPickerProps) {
    const [value, setValue] = useState(valueProp);
    const initialValue = useRef(valueProp);
    const onChangeRef = useRef(onChange);
    onChangeRef.current = onChange;

    // Form reset: the inputs are controlled, so a reset changes the DOM without
    // telling React, and the component — and its consumer, told by onChange —
    // would keep a value the form no longer submits. Restore the initial value instead — one tick later, after the
    // browser has reset the DOM, and not when the reset was cancelled.
    const rootRef = useRef<HTMLFieldSetElement>(null);
    useEffect(() => {
        const root = rootRef.current;
        const form = root?.closest("form");
        if (!root || !form) return;
        let timer: ReturnType<typeof setTimeout> | undefined;
        const onReset = (event: Event) => {
            clearTimeout(timer);
            timer = setTimeout(() => {
                if (event.defaultPrevented) return;
                // Tell the consumer, as a user's choice would: its last onChange
                // may name a value the form no longer holds.
                setValue((current) => {
                    if (current !== initialValue.current)
                        onChangeRef.current?.(initialValue.current);
                    return initialValue.current;
                });
                for (const input of root.querySelectorAll<HTMLInputElement>(
                    'input[type="radio"]',
                )) {
                    input.checked = input.value === String(initialValue.current);
                }
            }, 0);
        };
        form.addEventListener("reset", onReset);
        return () => {
            clearTimeout(timer);
            form.removeEventListener("reset", onReset);
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);
    const stars = [1, 2, 3, 4, 5];

    const handleChange = (star: number) => {
        setValue(star);
        onChange?.(star);
    };

    return (
        <fieldset
            ref={rootRef}
            className={`five-star-rating-picker ${className}`}
            role="radiogroup"
            aria-label={label}
            disabled={disabled}
            {...restProps}
        >
            {stars.map((star) => (
                <React.Fragment key={star}>
                    <label>
                        <input
                            type="radio"
                            name={name}
                            value={star}
                            checked={value === star}
                            onChange={() => handleChange(star)}
                        />
                        {starLabel ? starLabel(star) : star}
                    </label>
                </React.Fragment>
            ))}
        </fieldset>
    );
}
